import numpy as np

def h(state, landmark):
    """Range and bearing from a robot at state = (x, y, theta) to a landmark (lx, ly)."""
    dx, dy = landmark[0] - state[0], landmark[1] - state[1]
    return np.array([np.hypot(dx, dy), np.arctan2(dy, dx) - state[2]])

def jacobian(state, landmark):
    """The 2x3 matrix of partial derivatives of h with respect to (x, y, theta)."""
    return np.zeros((2, 3))

